function recipe(r) {
  return {
    ...r,
    title: bi(r.titleEn, r.titleKu),
    description: bi(r.descriptionEn, r.descriptionKu),
    ingredients: (r.ingredients || []).map((ing) => ({
      ...ing,
      name: bi(ing.nameEn, ing.nameKu),
    })),
    instructions: {
      en: r.instructionsEn || [],
      ku: r.instructionsKu || [],
    },
    substitutions: bi(r.substitutionsEn || "", r.substitutionsKu || ""),
    storageInstructions: bi(r.storageEn || "", r.storageKu || ""),
    whyFits: bi(r.whyFitsEn || "", r.whyFitsKu || ""),
  };
}

