export const NUTRITION_RECIPES = RAW_RECIPES.map((r, i) =>
  recipe({
    ...r,
    slug: r.id,
    image: IMG_LIST[i % IMG_LIST.length],
    isFeatured: FEATURED_IDS.has(r.id),
    isTrending: TRENDING_IDS.has(r.id),
  })
);

export function getRecipeBySlug(slug) {
  return NUTRITION_RECIPES.find((r) => r.slug === slug || r.id === slug);
}

export function getRecipesByCategory(catId) {
  if (!catId || catId === "all") return NUTRITION_RECIPES;
  return NUTRITION_RECIPES.filter((r) => (r.categories || []).includes(catId));
}

export function getFeaturedRecipes() {
  return NUTRITION_RECIPES.filter((r) => r.isFeatured);
}

export function getTrendingRecipes() {
  return NUTRITION_RECIPES.filter((r) => r.isTrending);
}

export function searchRecipes(query) {
  const q = String(query || "").trim().toLowerCase();
  if (!q) return NUTRITION_RECIPES;
  return NUTRITION_RECIPES.filter((r) => {
    const haystack = [
      r.title?.en,
      r.title?.ku,
      r.description?.en,
      r.description?.ku,
      r.cuisine,
      ...(r.categories || []),
      ...(r.ingredients || []).map(
        (ing) => `${ing.name?.en || ""} ${ing.name?.ku || ""}`
      ),
    ]
      .join(" ")
      .toLowerCase();
    return haystack.includes(q);
  });
}
